"""Write translated functions and their symbol table as C source."""

import re


def c_name(addr):
    return f'f_{addr:08x}'


def _comment(insn):
    return f'/* {insn.address:08x}: {insn.mnemonic} {insn.op_str}'.rstrip() + ' */'


def emit(functions, header_name):
    """`functions` is a list of (Function, [(insn, [C statements])]).

    Returns (c_source, header_source).
    """
    c = [
        '/* Generated by recomp. Do not edit. */',
        f'#include "{header_name}"',
        '',
    ]
    for fn, body in functions:
        c.append(f'/* {fn.name} */')
        c.append(f'void {c_name(fn.addr)}(Ctx *ctx)')
        c.append('{')
        for insn, stmts in body:
            c.append(f'    {_comment(insn)}')
            c.extend(f'    {s}' for s in stmts)
        c.append('}')
        c.append('')

    c.append('const RecompSym recomp_syms[] = {')
    for fn, _ in functions:
        c.append(f'    {{ "{fn.name}", 0x{fn.addr:08x}u, {c_name(fn.addr)} }},')
    c.append('};')
    c.append('const size_t recomp_nsyms = sizeof recomp_syms / sizeof recomp_syms[0];')
    c.append('')
    c.append('GuestFn recomp_lookup(const char *name)')
    c.append('{')
    c.append('    for (size_t i = 0; i < recomp_nsyms; i++)')
    c.append('        if (strcmp(recomp_syms[i].name, name) == 0)')
    c.append('            return recomp_syms[i].fn;')
    c.append('    return NULL;')
    c.append('}')

    guard = 'RECOMP_' + re.sub(r'\W', '_', header_name).upper()
    h = [
        '/* Generated by recomp. Do not edit. */',
        f'#ifndef {guard}',
        f'#define {guard}',
        '',
        '#include "context.h"',
        '',
    ]
    h.extend(f'void {c_name(fn.addr)}(Ctx *ctx);  /* {fn.name} */' for fn, _ in functions)
    h.append('')
    h.append('#endif')

    return '\n'.join(c) + '\n', '\n'.join(h) + '\n'
